def minimumTotalPrice(self, n, edges, price, trips):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    count = [0] * n
    def dfs_path(u, parent, target, path):
        path.append(u)
        if u == target:
            for node in path:
                count[node] += 1
            path.pop()
            return True
        for v in adj[u]:
            if v != parent:
                if dfs_path(v, u, target, path):
                    path.pop()
                    return True
        path.pop()
        return False
    for s, t in trips:
        dfs_path(s, -1, t, [])
    def dp(u, parent):
        full = price[u] * count[u]
        half = full // 2
        for v in adj[u]:
            if v != parent:
                f, h = dp(v, u)
                full += min(f, h)
                half += f
        return full, half
    f, h = dp(0, -1)
    return min(f, h)

def colorRed(self, n):
    # Pattern-based construction
    res = [[1, 1]]
    for row in range(2, n + 1):
        if row % 4 == 2:
            res.append([row, 2])
        elif row % 4 == 3:
            res.append([row, row * 2 - 1])
        elif row % 4 == 0:
            for col in range(row * 2 - 1, 0, -4):
                res.append([row, col])
        else:  # row % 4 == 1 and row > 1
            for col in range(2, row * 2, 4):
                res.append([row, col])
    return res

