import asyncio
async def cancellable(generator, cancel_token):
    try:
        result = None
        while True:
            if cancel_token.is_set():
                raise asyncio.CancelledError()
            result = next(generator)
    except StopIteration as e:
        return e.value

def getSubarrayBeauty(self, nums, k, x):
    cnt = [0] * 101  # offset: idx 0 = value -50
    res = []
    for i in range(len(nums)):
        if nums[i] < 0:
            cnt[nums[i] + 50] += 1
        if i >= k and nums[i - k] < 0:
            cnt[nums[i - k] + 50] -= 1
        if i >= k - 1:
            count = 0
            for j in range(50):  # only negatives
