def minOperations(self, nums):
    from math import gcd
    n = len(nums)
    ones = nums.count(1)
    if ones:
        return n - ones
    min_len = float('inf')
    for i in range(n):
        g = 0
        for j in range(i, n):
            g = gcd(g, nums[j])
            if g == 1:
                min_len = min(min_len, j - i)
                break
    return -1 if min_len == float('inf') else min_len + n - 1

def findMaximalUncoveredRanges(self, n, ranges):
    if not ranges:
        return [[0, n - 1]]
    ranges.sort()
    merged = []
    for l, r in ranges:
        if merged and l <= merged[-1][1] + 1:
            merged[-1][1] = max(merged[-1][1], r)
        else:
            merged.append([l, r])
    res = []
    if merged[0][0] > 0:
        res.append([0, merged[0][0] - 1])
    for i in range(1, len(merged)):
        res.append([merged[i-1][1] + 1, merged[i][0] - 1])
    if merged[-1][1] < n - 1:
        res.append([merged[-1][1] + 1, n - 1])
    return res

