def minimumCost(self, start, target, specialRoads):
    import heapq
    def dist(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])
    nodes = [tuple(start), tuple(target)]
    roads = []
    for x1,y1,x2,y2,c in specialRoads:
        roads.append(((x1,y1),(x2,y2),c))
        nodes.append((x1,y1))
        nodes.append((x2,y2))
    nodes = list(set(nodes))
    best = {node: float('inf') for node in nodes}
    best[tuple(start)] = 0
    heap = [(0, tuple(start))]
    while heap:
        d, u = heapq.heappop(heap)
        if u == tuple(target):
            return d
        if d > best[u]:
            continue
        for v in nodes:
            nd = d + dist(u, v)
            if nd < best[v]:
                best[v] = nd
                heapq.heappush(heap, (nd, v))
        for (s, e, c) in roads:
            nd = d + dist(u, s) + c
            if nd < best[e]:
                best[e] = nd
                heapq.heappush(heap, (nd, e))
    return best[tuple(target)]

def smallestBeautifulString(self, s, k):
    s = list(s)
    n = len(s)
    i = n - 1
    s[i] = chr(ord(s[i]) + 1)
    while i < n:
        if s[i] >= chr(ord('a') + k):
            i -= 1
            if i < 0:
                return ''
            s[i] = chr(ord(s[i]) + 1)
        elif (i >= 1 and s[i] == s[i-1]) or (i >= 2 and s[i] == s[i-2]):
            s[i] = chr(ord(s[i]) + 1)
        else:
            i += 1
            if i < n:
                s[i] = 'a'
    return ''.join(s)

def tourOfKnight(self, m, n, r, c):
    board = [[-1]*n for _ in range(m)]
    moves = [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]
    board[r][c] = 0
    def degree(x, y):
        return sum(1 for dx,dy in moves if 0<=x+dx<m and 0<=y+dy<n and board[x+dx][y+dy]==-1)
    def solve(x, y, step):
        if step == m * n:
            return True
        nexts = []
        for dx, dy in moves:
            nx, ny = x+dx, y+dy
            if 0<=nx<m and 0<=ny<n and board[nx][ny]==-1:
                nexts.append((degree(nx,ny), nx, ny))
        nexts.sort()
        for _, nx, ny in nexts:
            board[nx][ny] = step
            if solve(nx, ny, step+1):
                return True
            board[nx][ny] = -1
        return False
    solve(r, c, 1)
    return board

