class FrequencyTracker:
    def __init__(self):
        self.val_freq = {}
        self.freq_count = {}
    def add(self, number):
        old = self.val_freq.get(number, 0)
        if old > 0:
            self.freq_count[old] -= 1
        self.val_freq[number] = old + 1
        self.freq_count[old + 1] = self.freq_count.get(old + 1, 0) + 1
    def deleteOne(self, number):
        old = self.val_freq.get(number, 0)
        if old == 0:
            return
        self.freq_count[old] -= 1
        self.val_freq[number] = old - 1
        if old - 1 > 0:
            self.freq_count[old - 1] = self.freq_count.get(old - 1, 0) + 1
    def hasFrequency(self, frequency):
        return self.freq_count.get(frequency, 0) > 0

def colorTheArray(self, n, queries):
    colors = [0] * n
    count = 0
    res = []
    for idx, color in queries:
        old = colors[idx]
        if old != 0:
            if idx > 0 and colors[idx-1] == old:
                count -= 1
            if idx < n-1 and colors[idx+1] == old:
                count -= 1
        colors[idx] = color
        if idx > 0 and colors[idx-1] == color:
            count += 1
        if idx < n-1 and colors[idx+1] == color:
            count += 1
        res.append(count)
    return res

