def countCompleteComponents(self, n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    visited = [False] * n
    res = 0
    for i in range(n):
        if visited[i]:
            continue
        # BFS
        queue = [i]
        visited[i] = True
        comp = []
        while queue:
            node = queue.pop()
            comp.append(node)
            for nei in adj[node]:
                if not visited[nei]:
                    visited[nei] = True
                    queue.append(nei)
        v = len(comp)
        e = sum(len(adj[x]) for x in comp) // 2
        if e == v * (v - 1) // 2:
            res += 1
    return res

def getKthCharacter(self, root, k):
    # Rope tree: left subtree chars come before right
    def dfs(node):
        if not node:
            return ''
        if node.val:
            return node.val
        return dfs(node.left) + dfs(node.right)
    s = dfs(root)
    return s[k - 1]

