# Python equivalent:
class EventEmitter:
    def __init__(self):
        self.events = {}
    def subscribe(self, event, cb):
        if event not in self.events:
            self.events[event] = []
        self.events[event].append(cb)
        return lambda: self.events[event].remove(cb)
    def emit(self, event, args=None):
        if args is None:
            args = []
        return [cb(*args) for cb in self.events.get(event, [])]

