def punishmentNumber(self, n):
    def check(s, target):
        if not s and target == 0:
            return True
        for i in range(1, len(s) + 1):
            if int(s[:i]) > target:
                break
            if check(s[i:], target - int(s[:i])):
                return True
        return False
    res = 0
    for i in range(1, n + 1):
        if check(str(i * i), i):
            res += i * i
    return res
